"""Render a self-contained browser workbook for human auditing of model outputs."""
from __future__ import annotations

import argparse
import json
from pathlib import Path

ROOT = Path("/workspace/zzc/GeneReg-Eval")


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--articles", default="data/intermediate/trrust_pubmed_articles_v1_20260826.jsonl")
    args = parser.parse_args()
    output = ROOT / args.output
    if output.exists():
        raise SystemExit(f"Refusing to overwrite existing output: {output}")
    with (ROOT / args.articles).open(encoding="utf-8") as source:
        articles = {str(x["pmid"]): x for x in (json.loads(line) for line in source if line.strip())}
    rows = []
    with (ROOT / args.input).open(encoding="utf-8") as source:
        for index, line in enumerate(source):
            if not line.strip():
                continue
            row = json.loads(line)
            item, article = row["input"], articles.get(str(row["input"]["pmid"]), {})
            rows.append({"id": f"{index}:{item['pmid']}", "pmid": str(item["pmid"]), "species": item.get("species"), "gold_tf": item.get("tf_mention"), "gold_target": item.get("object_mention"), "gold_mor": item.get("relation"), "model": row.get("review", {}), "validation_route": row.get("validation_route"), "validation_errors": row.get("validation_errors", []), "title": article.get("title", ""), "abstract": article.get("abstract", "")})
    output.parent.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(rows, ensure_ascii=False).replace("</", "<\\/")
    output.write_text(PAGE.replace("__DATA__", payload), encoding="utf-8")
    print(json.dumps({"output": str(output), "records": len(rows)}, ensure_ascii=False))


PAGE = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TRRUST 摘要人工审阅工作簿</title><style>
:root{--ink:#172b4d;--bg:#f1f5f9;--line:#cbd5e1}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Arial,"Microsoft YaHei",sans-serif}header{position:sticky;top:0;z-index:2;padding:14px 4%;background:#082f49;color:#fff}h1{font-size:20px;margin:0 0 4px}main{max-width:1440px;margin:auto;padding:18px}.box,.card{background:#fff;border:1px solid var(--line);border-radius:10px;padding:14px;margin-bottom:14px}.tools{display:flex;flex-wrap:wrap;gap:9px;align-items:center}select,button,textarea{font:inherit}select,button{padding:7px;border:1px solid #94a3b8;border-radius:6px;background:#fff}button.primary{background:#0369a1;color:#fff}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:8px}.metric{background:#f8fafc;padding:8px;border-radius:6px}.metric b{display:block;font-size:21px}.card[hidden]{display:none}.meta{display:flex;flex-wrap:wrap;gap:6px}.tag{background:#e0f2fe;padding:2px 8px;border-radius:999px;font-size:13px}.reject{background:#fee2e2;color:#b91c1c}.gold{margin:10px 0;padding:10px;background:#fef3c7;border-left:4px solid #d97706}.model{padding:10px;background:#e0f2fe;border-radius:6px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.source{white-space:pre-wrap;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;padding:12px}mark{background:#bbf7d0}.audit{margin-top:16px;border-top:2px solid #0ea5e9;padding-top:10px}.audit label{display:block;font-weight:bold;margin-top:9px}.audit select,.audit textarea{width:100%}.audit textarea{min-height:64px;padding:8px;border:1px solid #94a3b8;border-radius:5px}.note{color:#9a3412}.saved{color:#047857;font-size:13px}@media(max-width:750px){.grid{grid-template-columns:1fr}}</style><body><header><h1>TRRUST 摘要抽取：人工审阅工作簿</h1><small>只以英文 Title / Abstract 为证据。TRRUST Gold 与模型结论均是待核查对象；人工判断自动保存到当前浏览器，完成后下载 JSON 报告。</small></header><main><section class="box"><b>审阅规则：</b>先读原文标题和摘要，再判定完整 TF→Target→MoR 是否成立。不要依据 TRRUST 或常识补证。模型 evidence span 必须为原文连续片段，并能独立支持方向。</section><section class="box tools"><label>模型结论 <select id="fs"><option value="">全部</option><option>ABSTRACT_SUPPORTED</option><option>ABSTRACT_PARTIAL</option><option>ABSTRACT_INSUFFICIENT</option></select></label><label>validator <select id="fv"><option value="">全部</option><option>VALID</option><option>REJECT</option></select></label><label>人工状态 <select id="fa"><option value="">全部</option><option value="new">未审</option><option value="done">已审</option></select></label><button id="next" class="primary">下一条未审</button><button id="download">下载人工标注 JSON</button><button id="report">下载自动审阅报告 JSON</button><button id="clear">清空本浏览器标注</button></section><section id="sum" class="box summary"></section><section id="cards"></section></main><script>
const DATA=__DATA__,KEY='trrust-audit-workbook-v2:'+location.pathname;let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch(e){};const $=x=>document.querySelector(x),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const choices=['ABSTRACT_SUPPORTED','ABSTRACT_PARTIAL','ABSTRACT_INSUFFICIENT'],quality=['CORRECT','PARTIALLY_CORRECT','INCORRECT','NOT_APPLICABLE'];function a(id){return saved[id]||{final_status:'',span_quality:'',entity_quality:'',condition_quality:'',include:'',notes:''}}function opts(xs,v,empty){return `<option value="">${empty}</option>`+xs.map(x=>`<option ${v===x?'selected':''}>${x}</option>`).join('')}function save(id,k,v){let x=a(id);x[k]=v;saved[id]=x;localStorage.setItem(KEY,JSON.stringify(saved))}function render(){let done=Object.values(saved).filter(x=>x.final_status).length,count={};Object.values(saved).forEach(x=>{if(x.final_status)count[x.final_status]=(count[x.final_status]||0)+1});$('#sum').innerHTML=`<div class="metric"><b>${done} / ${DATA.length}</b>已审阅</div>${choices.map(x=>`<div class="metric"><b>${count[x]||0}</b>人工 ${x.replace('ABSTRACT_','')}</div>`).join('')}`;let fs=$('#fs').value,fv=$('#fv').value,fa=$('#fa').value;$('#cards').innerHTML=DATA.map((r,i)=>{let x=a(r.id),done=!!x.final_status;if((fs&&r.model.support_status!==fs)||(fv&&r.validation_route!==fv)||(fa==='new'&&done)||(fa==='done'&&!done))return '';let co=Object.entries(r.model.condition||{}).filter(z=>z[1]).map(z=>`${esc(z[0])}: ${esc(z[1])}`).join('<br>')||'<i>null</i>';return `<article class="card" id="r${i}"><div class="meta"><span class="tag">#${i+1}</span><span class="tag">PMID ${esc(r.pmid)}</span><span class="tag">${esc(r.species)}</span><span class="tag">模型 ${esc(r.model.support_status)}</span><span class="tag ${r.validation_route==='REJECT'?'reject':''}">${esc(r.validation_route)}</span><span class="tag">${done?'已审':'未审'}</span></div><div class="gold"><b>TRRUST Gold（待核查候选）</b><br>${esc(r.gold_tf)} → ${esc(r.gold_target)}；MoR: ${esc(r.gold_mor)}</div><div class="model"><b>模型输出</b><br>结论：${esc(r.model.support_status)}<br>原文实体：${esc(r.model.extracted_tf_mention)} → ${esc(r.model.extracted_target_mention)}<br>Evidence span：<mark>${esc(r.model.evidence_span)||'null'}</mark><br>Condition：${co}<br>模型备注：${esc(r.model.review_note)||'—'}<br>Validator errors：${(r.validation_errors||[]).map(esc).join('; ')||'—'}</div><div class="grid"><div><h3>Title</h3><div class="source">${esc(r.title)}</div></div><div><h3>Abstract（唯一证据来源）</h3><div class="source">${esc(r.abstract)}</div></div></div><div class="audit"><h3>人工审阅</h3><label>人工最终结论 *</label><select data-id="${r.id}" data-k="final_status">${opts(choices,x.final_status,'— 尚未判定 —')}</select><div class="grid"><div><label>evidence span 质量</label><select data-id="${r.id}" data-k="span_quality">${opts(quality,x.span_quality,'未评')}</select></div><div><label>实体抽取质量</label><select data-id="${r.id}" data-k="entity_quality">${opts(quality,x.entity_quality,'未评')}</select></div><div><label>condition 抽取质量</label><select data-id="${r.id}" data-k="condition_quality">${opts(quality,x.condition_quality,'未评')}</select></div><div><label>是否纳入后续集</label><select data-id="${r.id}" data-k="include">${opts(['INCLUDE','EXCLUDE','NEEDS_ADJUDICATION'],x.include,'未定')}</select></div></div><label>审阅备注（说明原文依据或模型错误）</label><textarea data-id="${r.id}" data-k="notes">${esc(x.notes)}</textarea><span class="saved">修改自动保存到浏览器</span></div></article>`}).join('')||'<p>没有符合筛选条件的记录。</p>';document.querySelectorAll('[data-id]').forEach(e=>e.oninput=e.onchange=()=>{save(e.dataset.id,e.dataset.k,e.value);render()})}function result(){let rows=DATA.map(r=>({record_id:r.id,pmid:r.pmid,model_support_status:r.model.support_status,validation_route:r.validation_route,human_review:a(r.id)})),done=rows.filter(x=>x.human_review.final_status),agree=done.filter(x=>x.model_support_status===x.human_review.final_status).length;return {report_type:'human_review_summary_v1',generated_at:new Date().toISOString(),total_records:DATA.length,reviewed_records:done.length,unreviewed_records:DATA.length-done.length,status_agreement_count:agree,status_agreement_rate:done.length?agree/done.length:null,records:rows}}function dl(x,n){let z=document.createElement('a');z.href=URL.createObjectURL(new Blob([JSON.stringify(x,null,2)],{type:'application/json'}));z.download=n;z.click();URL.revokeObjectURL(z.href)}$('#download').onclick=()=>dl(result().records,'human_review_annotations_v1.json');$('#report').onclick=()=>dl(result(),'human_review_report_v1.json');$('#clear').onclick=()=>{if(confirm('清空本浏览器保存的人工标注？')){saved={};localStorage.removeItem(KEY);render()}};$('#next').onclick=()=>{let i=DATA.findIndex(r=>!a(r.id).final_status);if(i>=0)document.querySelector('#r'+i)?.scrollIntoView({behavior:'smooth',block:'start'})};['fs','fv','fa'].forEach(x=>$('#'+x).onchange=render);render();
</script></body></html>'''


if __name__ == "__main__":
    main()
